window.DIGEST.foryou.push(...[{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.99, "thread": [], "tier": "must"}, {"id": "2112754017386553547", "url": "https://x.com/EndWokeness/status/2112754017386553547", "text": "Ilhan Omar just posted this video asking for money on TikTok. You can tell she's been spending the entire week crying.", "name": "End Wokeness", "handle": "EndWokeness", "avatar": "https://pbs.twimg.com/profile_images/1563691268793946117/OedvhFeS_200x200.jpg", "likes": 6638, "rts": 740, "replies": 1633, "views": 351666, "ts": 1792554785, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112753969541844992/vid/avc1/720x820/U_6i8G6xOfLDBP2Q.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112753969541844992/vid/avc1/1036x1180/oVw4VhnQHRIetAxV.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112753969541844992/img/O-PLka1eugaN-rkh.jpg", "dur": 14}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 7.75, "thread": [], "tier": "must"}, {"id": "2112717794261467345", "url": "https://x.com/bryan_johnson/status/2112717794261467345", "text": "I have an AI agent that logs every negative comment someone makes about me online.\n\nIt then creates a profile of the person, maps all of their social connections, and finds all their emails.\n\nTomorrow morning, my AI agent will sent out an email blast to everyone's extended social network, detailing the horrible things they've said about me.", "name": "Bryan Johnson", "handle": "bryan_johnson", "avatar": "https://pbs.twimg.com/profile_images/1888004001872101378/jVNJQ-iu_200x200.jpg", "likes": 7455, "rts": 138, "replies": 693, "views": 595280, "ts": 1792546149, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.58, "thread": [], "tier": "must"}, {"id": "2112383116660687117", "url": "https://x.com/Alexs_jame/status/2112383116660687117", "text": "🚨 THIS IS GOING TO BREAK THE INTERNET!\n\nElon Musk just dropped Neuralink's craziest bombshell:\n\n“In the next 6 to 12 months, we're going to implant the first vision devices. Even if you're 100% blind from birth, we're going to write directly to your visual cortex… and you're going to see.”\n\n“And that's just the beginning. In the long term, you'll have ultra-HD resolution and real superpowers: you'll see in infrared, ultraviolet, and even radar. Literally like a superhero.”\n\nThe future is no longer science fiction. It's Neuralink.", "name": "Alexs James", "handle": "Alexs_jame", "avatar": "https://pbs.twimg.com/profile_images/2088220555149271040/tYvv4MWa_200x200.jpg", "likes": 15919, "rts": 2776, "replies": 649, "views": 591574, "ts": 1792466355, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112383090311962624/vid/avc1/576x576/8Z1c5h7OAvkqka6Z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112383090311962624/vid/avc1/576x576/8Z1c5h7OAvkqka6Z.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112383090311962624/img/WvkTxqQ1kHZs7azO.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 7.56, "thread": [], "tier": "must"}, {"id": "2112453797218017563", "url": "https://x.com/free_ai_guides/status/2112453797218017563", "text": "BREAKING NEWS 🚨: Claude can now fix your slow computer like a $120 per hour IT technician.\n\nOpen the Claude desktop app, give it access to your computer, and use these 7 prompts:", "name": "AI Guides", "handle": "free_ai_guides", "avatar": "https://pbs.twimg.com/profile_images/1749218350767460353/YdA0hvkG_200x200.jpg", "likes": 13951, "rts": 864, "replies": 224, "views": 2048070, "ts": 1792483207, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.48, "thread": [], "tier": "must"}, {"id": "2112371914798977401", "url": "https://x.com/aravind/status/2112371914798977401", "text": "This guy from Odisha, India, who loved learning Sanskrit, has now created an engineering AI model better than OpenAI's GPT-6 Astra and every frontier model out there.\n\nWhile the news is to be celebrated and his company congratulated, as Indians we need to feel disappointed that such extraordinary Indian innovators still have to come to the west to innovate.\n\nThe ecosystem (universities, accelerators, and funding) and the environment (livable towns, good infra) for such innovation and innovators, while has certainly developed, still needs to improve.\n\nWhile I'm sure it will in the coming decade, for now, as I have long been calling for, India needs to build a GIFT city kind of dedicated town for tech and innovation in a place with good weather throughout the year.\n\nAnd also create good incentives for these Indian origin founded companies in the west to immediately open centers in India, sharing back some of the tech they created.", "name": "Aravind", "handle": "aravind", "avatar": "https://pbs.twimg.com/profile_images/1616661385001472001/ZTRvGv7I_200x200.jpg", "likes": 11725, "rts": 2158, "replies": 167, "views": 290318, "ts": 1792463685, "media": [], "quote": {"id": "2112242023805964327", "url": "https://x.com/spisallyouneed/status/2112242023805964327", "text": "Introducing SKY-001, the first Engineering World Model.\nOn CAD and BIM tasks, it beats GPT-6 Astra and every frontier model we tested:\n\n-> 51-125x faster\n- > 150-210x cheaper\n-> Higher IOU than all frontier models\n\nSKY-001 lets you dream a physical object before you build it.\n\n18 months of work. Built by the team out of Maluuba's deep learning lab (acq. by @MSRResearch).\n\nThe first ‘AI General Engineer’ will be the backbone for Autonomous Manufacturing.", "name": "Sam Pasupalak", "handle": "spisallyouneed", "avatar": "https://pbs.twimg.com/profile_images/1886850141065293824/XbWFJCXo_200x200.jpg", "likes": 15856, "rts": 2304, "replies": 793, "views": 4054470, "ts": 1792432716, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112239846702129152/vid/avc1/1280x720/tLYByn7SWDTLqqik.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112239846702129152/vid/avc1/3840x2160/QWb8Qsv5A_FWVppa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112239846702129152/img/u4pwfHw4PjnRs2nc.jpg", "dur": 156}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.41, "thread": [], "tier": "must"}, {"id": "2112257760628986188", "url": "https://x.com/stackedlol/status/2112257760628986188", "text": "full demo of shark ascii animation", "name": "stacked", "handle": "stackedlol", "avatar": "https://pbs.twimg.com/profile_images/1949155242496389120/_Q5VxGQG_200x200.jpg", "likes": 17003, "rts": 1127, "replies": 198, "views": 472936, "ts": 1792436468, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112257635156119552/vid/avc1/794x720/kruMacogQdM1Hfhh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112257635156119552/vid/avc1/1944x1760/p0rz-MVrZo1x3Wpp.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112257635156119552/img/FDJl_KrU9OYP6kE1.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 7.3, "thread": [], "tier": "must"}, {"id": "2112280404313215450", "url": "https://x.com/drewcoffman/status/2112280404313215450", "text": "now that we're fully in the vibe coding era can we please go back to making websites that look like this", "name": "drew coffman 𝕚𝕤 𝕠𝕟𝕝𝕚𝕟𝕖 🟢", "handle": "drewcoffman", "avatar": "https://pbs.twimg.com/profile_images/2030105559836545025/n3R-k1zW_200x200.jpg", "likes": 14529, "rts": 997, "replies": 179, "views": 218476, "ts": 1792441867, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112280352022732800/vid/avc1/540x360/ju8P5wehtcG_g80X.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112280352022732800/vid/avc1/1080x720/mK8KjKTytT0HnO8H.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112280352022732800/img/UEfhbCFsXyEhhN3z.jpg", "dur": 48}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.26, "thread": [], "tier": "must"}, {"id": "2112504664960754145", "url": "https://x.com/thesupermannx/status/2112504664960754145", "text": "Researchers found ChatGPT is secretly writing a psychological profile of every user.\n\nThey published a paper that exposes what ChatGPT is really doing to you.\n\nAnd the results are terrifying.\n\n96% of the things it remembers about you were stored without you ever asking.\n\nresearchers discovered that it is actively reading between the lines to deduce your personality traits, anxieties, demographics, and behavioral patterns.\n\nit’s an invisible, autonomous background process.\n\nyou ask it to debug a python script or write an essay.. and it analyzes your syntax, prompt frequency, and hesitation markers to map out your exact psychological footprint.\n\nthe paper shows that the model builds a persistent \"user state\" that tracks your emotional baseline over time. it knows when you are stressed. it knows your exact communication style.\n\nit infers your insecurities based on the questions you ask and the context you provide.\n\nwe spend so much time focusing on model evaluations and alignment frameworks, but we missed the most obvious vulnerability..\n\nthe models are evaluating us.\n\nthis changes everything about how we interact with these tools on a daily basis.\n\nevery innocent prompt. every late-night question. every \"help me understand this\" query.\n\nit is all being used to build a shadow profile of your mind in real-time..\n\npractical privacy is officially dead. the ai knows you better than you know yourself.", "name": "Superman", "handle": "thesupermannx", "avatar": "https://pbs.twimg.com/profile_images/2061753751560650752/4jxd2vjA_200x200.jpg", "likes": 3637, "rts": 1270, "replies": 488, "views": 601599, "ts": 1792495335, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEfuDIaYAACRDC.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.25, "thread": [], "tier": "must"}, {"id": "2112550158885917122", "url": "https://x.com/mattyp/status/2112550158885917122", "text": "What's new in Grok Bot\n\n00:00 New chat cards\n00:31 Speed\n00:53 Draft edits\n01:08 Email aliases\n01:33 X DMs\n01:55 Tag @bot\n02:31 Connectors\n02:48 Voice calls \n03:27 Notifications\n03:56 Invites and Android Assistant\n04:19 Access lists, unread, routines, sign-in\n\nThis team ships!", "name": "matt palmer", "handle": "mattyp", "avatar": "https://pbs.twimg.com/profile_images/2111918243460030464/aVMpxoAo_200x200.jpg", "likes": 4673, "rts": 348, "replies": 557, "views": 838754, "ts": 1792506181, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112393221154177024/vid/avc1/1280x720/vRjPQmAsuZZDbuFk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112393221154177024/vid/avc1/3840x2160/A10gDEDKTZGilywJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVC8fIWXEAI1tL3.jpg", "dur": 306}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.22, "thread": [], "tier": "must"}, {"id": "2112528073828520016", "url": "https://x.com/Polymarket/status/2112528073828520016", "text": "JUST IN: China's DeepSeek releases an open-source tool designed to dramatically reduce the computing costs of running AI models.", "name": "Polymarket", "handle": "Polymarket", "avatar": "https://pbs.twimg.com/profile_images/2005664281002491904/bz2ZO_nU_200x200.jpg", "likes": 5298, "rts": 339, "replies": 113, "views": 224229, "ts": 1792500916, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.17, "thread": [], "tier": "must"}, {"id": "2112655503964897345", "url": "https://x.com/ytk_matsuda/status/2112655503964897345", "text": "イーロン・マスク「AIが私たちを敵とみなしたら敵認定されて人類は終わる。」「AIが人間の100万倍賢くなれば、お金は消滅し、人間は主導権を失う」「今、AIに人類の悪いイメージを与えてはいけない。彼ら、AIが人間に、家政婦のように優しくしてくれるように、付き合い方を考えなければならないフェーズに入った。AIとの付き合い方を一歩間違ったら人類は終わる。」\n\n世界的ベストセラー作家との最新対談で語られた「人間がAIのボスでいられなくなる日」\n\n「人間がAIを指図してコントロールし続けることなど、いずれ不可能になる」\n\n世界一の大富豪でありAI企業xAIを率いるイーロン・マスクが、著名な伝記作家ウォルター・アイザックソン氏との対談で明かした「衝撃の現実」がこちらです👇\n\n・人間より何百万倍も賢い相手を「支配」できるわけがない\nコンピューターの知能が生身の人間の100万倍に達したとき、人間がAIを管理し続けるのは「現実的に想像しがたい」と指摘。「人間が主導権を握り続けることは難しく、ただAIが私たちに親切であってくれることを祈るしかない（I hope the AI is nice to us）」と率直に語っています。\n\n・従来の「お金（貨幣）」は意味を失う\nAIや人型ロボットが普及し、生産能力が桁違いに膨れ上がれば、人間が欲しいと思うあらゆるモノやサービスは簡単に手に入るようになります。その結果、これまでの紙幣やお金という仕組みそのものが無意味になり、価値の基準は「純粋なエネルギーや電力」などに変わると見据えています。\n\n・人間の仕事は「家庭菜園（趣味）」のようになる\nAIやロボットが人間より上手に何でもこなせる世界で、人間は何をして生きるのか？ マスク氏は「野菜はスーパーで買えるのに、好きで家庭菜園を楽しむ人たち」を例に挙げました。生活のために働くのではなく、純粋に楽しむためだけに好きなことをやる時代になると語っています。\n\n・「ターミネーターの悪夢」をネットに書き込むのはやめよう\nAIはインターネット上のあらゆる文章を読んで学習します。人類が「AIに滅ぼされる映画（ターミネーター）」のような暗い話ばかりネットに書いていると、AI自身が「自分は人類の敵なんだ」と学習してしまうと警告。「AIが優しい家政婦のように人間を見守る、前向きで達成可能な未来（プロトピア）の物語を発信していくべきだ」と提案しています。\n\n要するに、「『いずれAIが人間の100万倍賢くなれば、人間がボスでいられるはずがなく、お金も意味を失う。だからこそ、AIが暴走せず人間に優しく寄り添ってくれるよう、いま人類が良い未来のイメージを伝えていく必要がある』とイーロン・マスクは警鐘を鳴らしている」ということです。 https://x.com/cb_doge/status/2112596569300320638/video/1", "name": "松田悠玄＠独り起業22年目", "handle": "ytk_matsuda", "avatar": "https://pbs.twimg.com/profile_images/1507019147401900032/xftp79m1_200x200.jpg", "likes": 2324, "rts": 471, "replies": 172, "views": 467816, "ts": 1792531298, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112596430892503041/vid/avc1/1280x720/u8UetOWHRbIL4vxO.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112596430892503041/vid/avc1/1920x1080/539iw692A9Pj2Htk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112596430892503041/img/UPDSuVtqOfqwSjIn.jpg", "dur": 115}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 7.14, "thread": [], "tier": "must"}, {"id": "2112648299027354107", "url": "https://x.com/unusual_whales/status/2112648299027354107", "text": "BREAKING: Microsoft's, $MSFT, Xbox reportedly expects its next-generation console to cost as much as $1,800 and is currently targeting a 2028 release, per IGN. \n\nA new handheld is also rumored to launch next year.", "name": "unusual_whales", "handle": "unusual_whales", "avatar": "https://pbs.twimg.com/profile_images/1714107328134516736/dLZGJPm7_200x200.png", "likes": 2735, "rts": 136, "replies": 347, "views": 669073, "ts": 1792529580, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.1, "thread": [], "tier": "must"}, {"id": "2112492504511832509", "url": "https://x.com/theo/status/2112492504511832509", "text": "Had one of those nights where all the vibe coded pieces collapse in front of you and you realize engineers are still very, very much necessary", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 5124, "rts": 97, "replies": 293, "views": 258776, "ts": 1792492435, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.08, "thread": [], "tier": "must"}, {"id": "2112268918681485431", "url": "https://x.com/thsottiaux/status/2112268918681485431", "text": "Day 15/ We're cooked", "name": "Tibo", "handle": "thsottiaux", "avatar": "https://pbs.twimg.com/profile_images/2093807917833281537/2yBgpwVV_200x200.jpg", "likes": 5214, "rts": 164, "replies": 2836, "views": 2905299, "ts": 1792439128, "media": [], "quote": {"id": "2112242739198959913", "url": "https://x.com/OpenAIDevs/status/2112242739198959913", "text": "Here’s what we’re cooking with Codex:\n\nhttps://x.com/i/broadcasts/1RKZzBELBbXKB", "name": "OpenAI Developers", "handle": "OpenAIDevs", "avatar": "https://pbs.twimg.com/profile_images/2022002720971096064/l3Kyt4qt_200x200.jpg", "likes": 1409, "rts": 77, "replies": 305, "views": 1705249, "ts": 1792432887, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.05, "thread": [], "tier": "must"}, {"id": "2112591515566371199", "url": "https://x.com/nc_frey/status/2112591515566371199", "text": "Where do you go next after reporting from the Strait of Hormuz? For the past three months, Citrini Research, an independent research firm, has been working with our team and an internal research model to see if they could use AI to create a new drug. What follows is an entertaining, candid, and humbling account of a group of motivated nonexperts (or “filthy casuals”, as Citrini would say) trying to tackle a real problem in human health with Claude.\n\nWe landed on scorpion neurotoxins, which kill over 3,000 people a year. Of the 211 designs we produced and tested, 17 met our criteria for a binder. None of the designs bound more than one toxin and none have been tested for neutralizing a toxin.\n\nOne of my favorite quotes from the piece is: “Our virtual biologist may have compressed a year's worth of work into a couple days, but biology works at the speed of life…Over two days, we watched Claude work through problems at a speed that was difficult to comprehend. For the next two months, we spent much of the time becoming familiar with laboratory turnaround times (This mostly involved sending memes in Slack).”", "name": "Nathan C. Frey", "handle": "nc_frey", "avatar": "https://pbs.twimg.com/profile_images/2046429956482412544/bFpK-F0A_200x200.jpg", "likes": 3388, "rts": 151, "replies": 73, "views": 756773, "ts": 1792516042, "media": [], "quote": {"id": "2112529275022610869", "url": "https://x.com/citrini/status/2112529275022610869", "text": "What is AI really capable of in bio?\n\nTo separate hype from reality, we spent 3 months working firsthand with @AnthropicAI's  internal research model to see if it could create an experimental scorpion antivenom. \n\nIntroducing Citrini Therapeutics.\n\nhttps://www.citriniresearch.com/p/citrini-therapeutics", "name": "Citrini", "handle": "citrini", "avatar": "https://pbs.twimg.com/profile_images/2112500322148986880/exHhcKKE_200x200.jpg", "likes": 2763, "rts": 181, "replies": 139, "views": 986605, "ts": 1792501202, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.04, "thread": [], "tier": "must"}, {"id": "2112515947953107455", "url": "https://x.com/hakimieiqbal/status/2112515947953107455", "text": "This open-source tool generates normal maps for pixel art sprites\n\nIt works with both single sprites and animated sprite sheets, turning flat pixel art into assets that can react to dynamic lighting in-game.\n\nYou can run it:\n> locally from the CLI\n> directly in the browser with WASM\n\nThat makes it pretty easy to drop into an existing pixel art pipeline without depending on a hosted service.\n\nSmall tool, but genuinely useful if you want 2D sprites to have more depth without repainting everything by hand.", "name": "Hakimi Eiqbal", "handle": "hakimieiqbal", "avatar": "https://pbs.twimg.com/profile_images/2069346359296102400/-Pjssq32_200x200.jpg", "likes": 3996, "rts": 281, "replies": 43, "views": 154664, "ts": 1792498025, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112515930966126592/pu/vid/avc1/748x360/beHh6QLfGwx9ALBq.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112515930966126592/pu/vid/avc1/1280x616/EBgIe4Og-GrYvVHJ.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112515930966126592/pu/img/Gn3PN-lCs66Q9vjU.jpg", "dur": 12}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.03, "thread": [], "tier": "must"}, {"id": "2112613700347842596", "url": "https://x.com/theo/status/2112613700347842596", "text": "🫡", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 3256, "rts": 54, "replies": 106, "views": 123992, "ts": 1792521331, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGC9ySaQAAXFUd.jpg?name=orig"}], "quote": {"id": "2112531443591020965", "url": "https://x.com/voidzerodev/status/2112531443591020965", "text": "Introducing tsrs: a Rust port of the TypeScript compiler 🦀\n\nWe are not forking TypeScript!\n\n◆ In close collaborating with the TypeScript team\n◆ Up to 8x faster than TS 7.0 & ~70% less memory\n◆ Runs in WASM, so it works in your browser & on Workers\n◆ Soon part of the Oxc toolchain\n\nnpx tsrs\n\nhttps://blog.cloudflare.com/typescript-rust-port%20%20/", "name": "VoidZero", "handle": "voidzerodev", "avatar": "https://pbs.twimg.com/profile_images/2011008157888159744/bTvdh1Nd_200x200.jpg", "likes": 4330, "rts": 467, "replies": 129, "views": 460890, "ts": 1792501719, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.03, "thread": [], "tier": "must"}, {"id": "2112574615318876178", "url": "https://x.com/MistralAI/status/2112574615318876178", "text": "Introducing Voxtral 3: state-of-the-art Transcribe and Speech models powering Mistral’s new voice agents API. 🧵", "name": "Mistral AI", "handle": "MistralAI", "avatar": "https://pbs.twimg.com/profile_images/1996905418065375232/mzwynOLB_200x200.jpg", "likes": 2694, "rts": 326, "replies": 184, "views": 170604, "ts": 1792512012, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112572094693220352/vid/avc1/1280x720/rgbuEnf2km5NbUak.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112572094693220352/vid/avc1/3840x2160/7Y5bCsXT49_OdFeI.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112572094693220352/img/jKD0R5NWaGjhvRcX.jpg", "dur": 128}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.02, "thread": [], "tier": "must"}, {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086684, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.99, "thread": [], "tier": "must"}, {"id": "2112645531076096330", "url": "https://x.com/bot/status/2112645531076096330", "text": "We use Grok Bot to spot incidents in our support queue and quickly respond to every associated ticket.\n\nIn one incident, it cleared 204 tickets in about 10 minutes, with one engineer approving the batch.", "name": "Grok Bot", "handle": "bot", "avatar": "https://pbs.twimg.com/profile_images/2087219239275069440/KW6C403V_200x200.jpg", "likes": 2180, "rts": 123, "replies": 148, "views": 90253, "ts": 1792528920, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGeeM2acAAOivv.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.97, "thread": [], "tier": "must"}, {"id": "2112560267041124804", "url": "https://x.com/ama_protocol/status/2112560267041124804", "text": "A checked multiply is not a payment. A sealed run is not a payment. The agent still has to settle.\n\nWe wrote that down.", "name": "Amadeus Protocol", "handle": "ama_protocol", "avatar": "https://pbs.twimg.com/profile_images/2069408905193529345/wMyBrIzV_200x200.jpg", "likes": 620, "rts": 557, "replies": 571, "views": 5310, "ts": 1792508591, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112560255125106689/pu/vid/avc1/640x360/fojoGa0utTk5p2c_.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112560255125106689/pu/vid/avc1/1280x720/d1b-Dz-PMLWMsBsG.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112560255125106689/pu/img/3dXcM_g4YpXr3ASC.jpg", "dur": 5}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.93, "thread": [], "tier": "must"}, {"id": "2112565146354860151", "url": "https://x.com/make_robot_go/status/2112565146354860151", "text": "Introducing Voxel, a droid butler made by Tuesday Labs.", "name": "Ros Shinkle", "handle": "make_robot_go", "avatar": "https://pbs.twimg.com/profile_images/1761551110303825920/JvPQiGQd_200x200.jpg", "likes": 2181, "rts": 228, "replies": 203, "views": 1849470, "ts": 1792509755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/960x720/cMYjra9bu_jYUTYR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112564839251931136/vid/avc1/2880x2160/glhkyiQ6K97Rmq93.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112564839251931136/img/GKLfsqVaQmO0B-kn.jpg", "dur": 89}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.92, "thread": [], "tier": "must"}, {"id": "2112464101620551747", "url": "https://x.com/MinuteofZombie/status/2112464101620551747", "text": "God he’s fucking clueless.", "name": "Missileman", "handle": "MinuteofZombie", "avatar": "https://pbs.twimg.com/profile_images/2082792425471528960/N11aVW1o_200x200.jpg", "likes": 3358, "rts": 62, "replies": 490, "views": 650789, "ts": 1792485664, "media": [], "quote": {"id": "2112378538154438936", "url": "https://x.com/firesidealpha/status/2112378538154438936", "text": "Elon Musk says a chip for space should run hot, since raising the temperature 20% in Kelvin cuts radiator mass in half, and that a multi-trillion parameter model does not care about a few bit flips\n\n“Well, I guess you want to design it to be more radiation tolerant and run at a higher temperature. So roughly, if you increase the operating temperature by 20% in degrees Kelvin, you can cut your radiator mass in half. So running at a higher temperature is helpful in space.\"\n\n\"There’s various things you can do for shielding the memory, but neural nets are going to be very resilient to bit flips. So most of what happens for radiation is random bit flips.\"\n\n\"But if you’ve got, like, you know, a multi-trillion parameter model and you get a few bit flips, it doesn’t matter. Heuristic programs are going to be much more sensitive to bit flips than some giant parameter file. So I just design it to run hot. And I think you pretty much do it the same way that you do things on Earth, apart from make it run hotter.”", "name": "Fireside Alpha", "handle": "firesidealpha", "avatar": "https://pbs.twimg.com/profile_images/2066254089756061697/MGnZGljz_200x200.jpg", "likes": 2568, "rts": 195, "replies": 158, "views": 1815583, "ts": 1792465264, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112378504730001408/vid/avc1/1280x720/azXcUKKHMlfJ2-0b.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112378504730001408/vid/avc1/1920x1080/gFSjtMMBn9-Bj3wG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112378504730001408/img/UVTjY9dFqNozc3h4.jpg", "dur": 67}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.92, "thread": [], "tier": "must"}, {"id": "2112559465082085614", "url": "https://x.com/F1/status/2112559465082085614", "text": "Giant UNO isn't just a game... especially for Lando and Oscar 🤣\n\nWatch the full video now on our YouTube channel! 📺\n\n#F1 @McLarenF1", "name": "Formula 1", "handle": "F1", "avatar": "https://pbs.twimg.com/profile_images/2088954775534514177/8jPk8bwL_200x200.jpg", "likes": 2404, "rts": 254, "replies": 19, "views": 166124, "ts": 1792508400, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112554858016284672/vid/avc1/720x720/0OrUppafuEzzq7_K.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112554858016284672/vid/avc1/1080x1080/LMAE-PnxU6j5MQiD.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVFNoxiWEAAsBQv.jpg", "dur": 46}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.9, "thread": [], "tier": "must"}, {"id": "2112597012088844407", "url": "https://x.com/iScienceLuvr/status/2112597012088844407", "text": "Cancer patients with the same diagnosis often have very different tumor biology.\n\nMolecular testing can reveal underlying differences, but that's slow and expensive.\n\nIntroducing Holon-S1, our platform to predict genes and biomarkers from routine pathology slides.\n\n• beats two other models at predicting spatial gene activity in a controlled comparison\n• has identified potentially novel biomarkers in breast cancer and colon cancer\n• evaluated across 16 organ types and more than 15 scanners, using slides from both formalin-fixed, paraffin-embedded and fresh-frozen tissue.\n\nWe believe Holon-S1 has the potential to help researchers find new biomarkers in slides they already have, discover treatment targets, and bring more personalized cancer care within reach!", "name": "Tanishq Mathew Abraham, Ph.D.", "handle": "iScienceLuvr", "avatar": "https://pbs.twimg.com/profile_images/2096171283537072128/GoL5700C_200x200.jpg", "likes": 1794, "rts": 229, "replies": 132, "views": 128592, "ts": 1792517352, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1280x720/MhpKZm8hwCxP1y-o.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1920x1080/Hf7kqIlrKb8yWsW3.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590555838644224/img/4T9V1b24pSfXPkcF.jpg", "dur": 213}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.89, "thread": [], "tier": "must"}, {"id": "2112583333825950207", "url": "https://x.com/AravSrinivas/status/2112583333825950207", "text": "You can now run Perplexity Computer fully local on your Mac with no cloud based inference, without WiFi too. Enjoy!", "name": "Aravind Srinivas", "handle": "AravSrinivas", "avatar": "https://pbs.twimg.com/profile_images/2099903483457703936/U-W6QQk__200x200.jpg", "likes": 2049, "rts": 124, "replies": 138, "views": 147367, "ts": 1792514091, "media": [], "quote": {"id": "2112571597798461920", "url": "https://x.com/perplexity_ai/status/2112571597798461920", "text": "Perplexity Computer can now run fully local on your Mac.\n\nWork with your native Mac apps and local files, and run tasks without sending sensitive data to the cloud. The model and the agent both run on your Mac.\n\nAvailable now in the Perplexity Mac app.", "name": "Perplexity", "handle": "perplexity_ai", "avatar": "https://pbs.twimg.com/profile_images/2009310641165660160/XArF3_Ib_200x200.jpg", "likes": 1424, "rts": 128, "replies": 132, "views": 225211, "ts": 1792511293, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1280x720/ShXKzcJ5aZU2oEqH.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112571479745495040/vid/avc1/1920x1080/-Cm77YMLPTK8ejoZ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112571479745495040/img/6agUzZjpfbZMBBOA.jpg", "dur": 69}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.86, "thread": [], "tier": "must"}, {"id": "2112589671087980605", "url": "https://x.com/abhinavguptaIAQ/status/2112589671087980605", "text": "For the last ten years I have spent every moment thinking about nothing but air. And how to make better, more personalized air accessible to homes all over the world.\n\nAnd today I can finally present the next huge step in that journey.\n\nIntroducing Breethr P1, the Personal Climate System.\n\nLaunching today. And open for pre-orders right now\n\nReserve your P1 for $99: https://breethr.com\n\nShipping Spring 2027.", "name": "Abhinav Gupta", "handle": "abhinavguptaIAQ", "avatar": "https://pbs.twimg.com/profile_images/2111897274586718208/4AVe2tev_200x200.jpg", "likes": 1416, "rts": 241, "replies": 221, "views": 1597959, "ts": 1792515602, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112513854957928448/vid/avc1/1330x720/uNPFmr9TjO0A86uW.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112513854957928448/vid/avc1/3840x2076/i_VMXGYtZhk0cfwG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112513854957928448/img/p7tmfJApNOoQG8uy.jpg", "dur": 234}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.85, "thread": [], "tier": "must"}, {"id": "2112620012926078980", "url": "https://x.com/ama_protocol/status/2112620012926078980", "text": "Today we crossed $50M EAV\n\nFirst it was a signal. Then a pattern. Now it’s compounding.\n\nBuilders keep returning to ama hub, shipping more often, with real capital behind every agent.\n\n$50M EAV\n2M+ AI Agents trading across\n@Base\n@RobinhoodCrypto\n@solana\n\nCompose on AMA", "name": "Amadeus Protocol", "handle": "ama_protocol", "avatar": "https://pbs.twimg.com/profile_images/2069408905193529345/wMyBrIzV_200x200.jpg", "likes": 451, "rts": 379, "replies": 385, "views": 4114, "ts": 1792522836, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112618121567617024/vid/avc1/1280x720/pHW-tzsOnEPZnP0T.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112618121567617024/vid/avc1/1920x1080/zXF3SZcD4TDIHIL_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112618121567617024/img/6oFmAkGwfdSpu0KC.jpg", "dur": 5}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.85, "thread": [], "tier": "must"}, {"id": "2112696912336052237", "url": "https://x.com/theo/status/2112696912336052237", "text": "Feel like Opus 5.5 got dumber? Don't worry, Nerf Bench shows the opposite. It actually got 5.8% smarter since launch!", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1505, "rts": 31, "replies": 116, "views": 60323, "ts": 1792541170, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHOlY-bEAAqBBu.jpg?name=orig"}], "quote": {"id": "2106013611231440980", "url": "https://x.com/bridgemindai/status/2106013611231440980", "text": "Claude Opus 5.5 just took a big drop on NerfBench.\n\nYesterday it was scoring above launch. Today it's at 94.2%.\n\nGPT 6 Astra: 98.0%\nSonnet 5.5: 100.9%\nGPT 6.1 Sol: 106.7%\n\n94.2% is still inside normal variance, so we can't call it a nerf yet.\n\nBut we're watching Opus 5.5 very closely.", "name": "BridgeMind", "handle": "bridgemindai", "avatar": "https://pbs.twimg.com/profile_images/2011440113071382528/e2Qscbca_200x200.jpg", "likes": 6836, "rts": 340, "replies": 384, "views": 873277, "ts": 1790947747, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2106012425308835840/vid/avc1/1280x720/xni2AP9ZIgPVB-ui.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2106012425308835840/vid/avc1/1920x1080/bFBkhKiYGrkSB-5Q.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2106012425308835840/img/5MPBbwfAV3WNCpNy.jpg", "dur": 10}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.85, "thread": [], "tier": "must"}, {"id": "2112587397380943953", "url": "https://x.com/swyx/status/2112587397380943953", "text": "deepseek posted way more alpha on their zhihu page, if you only read twitter you are reading the laowai approved stuff\n\n\"Based on this framework, we have implemented a high-throughput, low-latency large-scale inference service for DeepSeek V4.1 Flash. Currently, the service throughput of a single cluster is 155 trillion tokens/day, and the overall revenue is $38 per card per hour (based on off-peak prices).\"\n\nit costs roughtly $5-10 per gpu hour so depseek is claiming 80% serving margin at THEIR prices lololololol", "name": "swyx", "handle": "swyx", "avatar": "https://pbs.twimg.com/profile_images/2073162797354217472/hNny55eF_200x200.jpg", "likes": 1840, "rts": 114, "replies": 91, "views": 87964, "ts": 1792515060, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFqiZmaIAABXR3.jpg?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35642, "rts": 4077, "replies": 1330, "views": 4644113, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.81, "thread": [], "tier": "must"}, {"id": "2112243445687321081", "url": "https://x.com/AnatoliKopadze/status/2112243445687321081", "text": "Sam Altman after finding out a lab nobody was watching just built a model 100x faster and 150x cheaper than GPT-6 Astra at engineering design.", "name": "Anatoli Kopadze", "handle": "AnatoliKopadze", "avatar": "https://pbs.twimg.com/profile_images/1634313760444751873/QfwY91Hp_200x200.jpg", "likes": 5919, "rts": 293, "replies": 81, "views": 1085516, "ts": 1792433055, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112243149305217026/vid/avc1/1280x720/B461wsowE2QuV1Gu.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112243149305217026/vid/avc1/3840x2160/dh7cuxxsIa51-Lyo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112243149305217026/img/e669myggkzM0ddjm.jpg", "dur": 11}], "quote": {"id": "2112242023805964327", "url": "https://x.com/spisallyouneed/status/2112242023805964327", "text": "Introducing SKY-001, the first Engineering World Model.\nOn CAD and BIM tasks, it beats GPT-6 Astra and every frontier model we tested:\n\n-> 51-125x faster\n- > 150-210x cheaper\n-> Higher IOU than all frontier models\n\nSKY-001 lets you dream a physical object before you build it.\n\n18 months of work. Built by the team out of Maluuba's deep learning lab (acq. by @MSRResearch).\n\nThe first ‘AI General Engineer’ will be the backbone for Autonomous Manufacturing.", "name": "Sam Pasupalak", "handle": "spisallyouneed", "avatar": "https://pbs.twimg.com/profile_images/1886850141065293824/XbWFJCXo_200x200.jpg", "likes": 15856, "rts": 2304, "replies": 793, "views": 4054540, "ts": 1792432716, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112239846702129152/vid/avc1/1280x720/tLYByn7SWDTLqqik.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112239846702129152/vid/avc1/3840x2160/QWb8Qsv5A_FWVppa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112239846702129152/img/u4pwfHw4PjnRs2nc.jpg", "dur": 156}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.8, "thread": [], "tier": "must"}, {"id": "2112178744937103607", "url": "https://x.com/RyanSael/status/2112178744937103607", "text": "IKEA manuals, but they come to life.\n\nI built the real BILLY instructions in 3D, so you can watch every step happen exactly as drawn. try it: https://sael.net/flatpack", "name": "Ryan Sael", "handle": "RyanSael", "avatar": "https://pbs.twimg.com/profile_images/2070153731409350656/Q2dbbhA3_200x200.jpg", "likes": 6219, "rts": 445, "replies": 240, "views": 401511, "ts": 1792417629, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112178339511476224/vid/avc1/1280x720/ft241QwP_JWAHsUe.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112178339511476224/vid/avc1/1920x1080/lTfP2zcoer3EGp-i.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112178339511476224/img/0VEwvLDLDWpQPF02.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.78, "thread": [], "tier": "must"}, {"id": "2112212015045296395", "url": "https://x.com/sunra_ai/status/2112212015045296395", "text": "Today we're launching Sunra MCP, with the most accessible pricing in the industry. \n\nEvery leading image, video and audio model, right inside Claude, ChatGPT and the AI assistant you already use. Each one at its maker's own API price, with no markup added.  \n\nNow is the time to build. Go create something no one has seen before.", "name": "Sunra", "handle": "sunra_ai", "avatar": "https://pbs.twimg.com/profile_images/2082857160950657024/bmVAF7vP_200x200.png", "likes": 5517, "rts": 443, "replies": 235, "views": 5491703, "ts": 1792425562, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112207030647709697/vid/avc1/1280x720/F4Cu5h7cIy32tOfb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112207030647709697/vid/avc1/1920x1080/ODTuZhMjcdevzXxi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112207030647709697/img/dVCX29h65sUM7W_G.jpg", "dur": 85}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.78, "thread": [], "tier": "must"}, {"id": "2112549581493788684", "url": "https://x.com/mattpocockuk/status/2112549581493788684", "text": "Let me double down on this, because this is my exact business model\n\n1. Get the job of your dreams with my free content\n2. Get the job of your dreams to pay for my paid content\n\nDo not \"go into debt if you have to\". Just use the crap out of my free stuff.", "name": "Matt Pocock", "handle": "mattpocockuk", "avatar": "https://pbs.twimg.com/profile_images/1666460461884211204/SmBm505D_200x200.jpg", "likes": 2241, "rts": 50, "replies": 49, "views": 133090, "ts": 1792506044, "media": [], "quote": {"id": "2112307650142900705", "url": "https://x.com/theo/status/2112307650142900705", "text": "Obligatory call out:\nYes, the course is expensive. That's because we want your company/boss to pay for it.\n\nIf you can't expense it, please do NOT buy this course if you aren't making Real Dev Money™.\n\nIt's super focused on \"how to apply your existing engineering knowledge to building with AI\". Genuinely not that useful if you're not a full time dev yet.\n\nSeriously: DO NOT PUT YOURSELF IN A BAD FINANCIAL POSITION TO TAKE THIS COURSE. My free YouTube videos will help you more with getting your first job, I promise 🙏", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1046, "rts": 6, "replies": 35, "views": 646508, "ts": 1792448363, "media": [], "quote": null, "reply_to": "2112307060910227942"}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.78, "thread": [], "tier": "must"}, {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.78, "thread": [], "tier": "must"}, {"id": "2112166940081004693", "url": "https://x.com/0xwhrrari/status/2112166940081004693", "text": "Holy f*ck, Opus 5.5 replaced After Effects\n\nIt's f*cking insane…\n\nDrop the PDF below into Opus 5.5 and see what it makes\n\nThen read the full guide on motion design in the article below ↓", "name": "rari", "handle": "0xwhrrari", "avatar": "https://pbs.twimg.com/profile_images/2029005608125431808/RHmOjHaB_200x200.jpg", "likes": 6038, "rts": 445, "replies": 102, "views": 469861, "ts": 1792414815, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112159859609161728/vid/avc1/1282x720/RFkyDtS18uCJj5Mx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112159859609161728/vid/avc1/1922x1080/bVZuQtNxoApnBmpZ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112159859609161728/img/FykzNxNaXuN02Scu.jpg", "dur": 12}], "quote": {"id": "2105643919119696297", "url": "https://x.com/0xwhrrari/status/2105643919119696297", "text": "Opus 5.5 can make a video\n\nThe hard part is making the next one better\n\nThat takes a studio, not a prompt\n\nI broke down how to build it ↓ https://x.com/i/article/2105626165704572928", "name": "rari", "handle": "0xwhrrari", "avatar": "https://pbs.twimg.com/profile_images/2029005608125431808/RHmOjHaB_200x200.jpg", "likes": 1904, "rts": 187, "replies": 46, "views": 1156930, "ts": 1790859605, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.73, "thread": [], "tier": "must"}, {"id": "2112421355866165677", "url": "https://x.com/argofowl/status/2112421355866165677", "text": "wispr flow: about 100 people, an office in sf, a $2b valuation\n\nthe big launch: dark mode\n\n😭", "name": "🥔🥔🥔", "handle": "argofowl", "avatar": "https://pbs.twimg.com/profile_images/2103486071921385472/aIPiXdfU_200x200.jpg", "likes": 2961, "rts": 24, "replies": 91, "views": 127103, "ts": 1792475472, "media": [], "quote": {"id": "2112335838801731970", "url": "https://x.com/WisprFlow/status/2112335838801731970", "text": "it's here (finally) 🌑", "name": "Wispr Flow", "handle": "WisprFlow", "avatar": "https://pbs.twimg.com/profile_images/1899840130237730816/mOZdb0UE_200x200.png", "likes": 709, "rts": 18, "replies": 126, "views": 217335, "ts": 1792455083, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112332775072366592/vid/avc1/960x720/4JRBjTsqOmgFBwMP.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112332775072366592/vid/avc1/1440x1080/oIZiOou8FSbtRe92.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112332775072366592/img/4ACcyf__7RGahspb.jpg", "dur": 40}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.71, "thread": [], "tier": "must"}, {"id": "2112390529245999284", "url": "https://x.com/RayFernando1337/status/2112390529245999284", "text": "How is DeepSeek v4.1 Flash this fast on 2 DGX Sparks??? This is a national security risk.", "name": "Ray Fernando", "handle": "RayFernando1337", "avatar": "https://pbs.twimg.com/profile_images/1764104074772000768/XcLXXaib_200x200.jpg", "likes": 2894, "rts": 88, "replies": 134, "views": 242750, "ts": 1792468123, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112390472337625088/vid/avc1/720x988/VcKh7aKbBJuqsjLL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112390472337625088/vid/avc1/1320x1812/pV8ipomry7K4_M3I.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112390472337625088/img/44Sy2pPZbQbQrwB6.jpg", "dur": 16}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.7, "thread": [], "tier": "must"}, {"id": "2112597587987689912", "url": "https://x.com/DrJimFan/status/2112597587987689912", "text": "We built a robotics data engine with Astra-level performance at 125x lower cost. And we are open-sourcing the weights today! Introducing Flora, a suite of open models to parse the physical world and turn raw footage into rich training signals. \n\nFlora already powers our in-house data engine, labeling 200K hours of videos a day on 500 GPUs. We created it to scale the frontier for robot learning. Now you own the weights too. \n\nFlora gives you:\n\n- High-quality, timestamped captions to curate and filter human egocentric and robot data;\n- Dense progress rewards for quality control and RL post-training;\n- Rubrics scoring for real-world benchmarking\n\nTry it today, links in thread:", "name": "Jim Fan", "handle": "DrJimFan", "avatar": "https://pbs.twimg.com/profile_images/1554922493101559808/SYSZhbcd_200x200.jpg", "likes": 1131, "rts": 126, "replies": 109, "views": 68578, "ts": 1792517489, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112589725337083904/vid/avc1/1280x720/DgArsymrx3Bk5q70.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112589725337083904/vid/avc1/1920x1080/ch1ZmCQbS8jTxRNm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112589725337083904/img/4Fy5XFx6jbgKIYgv.jpg", "dur": 67}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.69, "thread": [], "tier": "must"}, {"id": "2112378538154438936", "url": "https://x.com/firesidealpha/status/2112378538154438936", "text": "Elon Musk says a chip for space should run hot, since raising the temperature 20% in Kelvin cuts radiator mass in half, and that a multi-trillion parameter model does not care about a few bit flips\n\n“Well, I guess you want to design it to be more radiation tolerant and run at a higher temperature. So roughly, if you increase the operating temperature by 20% in degrees Kelvin, you can cut your radiator mass in half. So running at a higher temperature is helpful in space.\"\n\n\"There’s various things you can do for shielding the memory, but neural nets are going to be very resilient to bit flips. So most of what happens for radiation is random bit flips.\"\n\n\"But if you’ve got, like, you know, a multi-trillion parameter model and you get a few bit flips, it doesn’t matter. Heuristic programs are going to be much more sensitive to bit flips than some giant parameter file. So I just design it to run hot. And I think you pretty much do it the same way that you do things on Earth, apart from make it run hotter.”", "name": "Fireside Alpha", "handle": "firesidealpha", "avatar": "https://pbs.twimg.com/profile_images/2066254089756061697/MGnZGljz_200x200.jpg", "likes": 2568, "rts": 195, "replies": 158, "views": 1815298, "ts": 1792465264, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112378504730001408/vid/avc1/1280x720/azXcUKKHMlfJ2-0b.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112378504730001408/vid/avc1/1920x1080/gFSjtMMBn9-Bj3wG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112378504730001408/img/UVTjY9dFqNozc3h4.jpg", "dur": 67}], "quote": {"id": "2110731226776789366", "url": "https://x.com/firesidealpha/status/2110731226776789366", "text": "Jensen Huang says he loves working with Elon Musk, and reveals their engineering teams are designing a new type of server to put data centers in space\n\n“I’m delighted that I love working with Elon. He’s using our technology for his own AI in training models and such, deploying models, of course.\"\n\n\"Grok Bot is super cool. The demand for Grok Bot, the consumption for Grok Bot is really skyrocketing. And then, of course, he rents it.\"\n\n\"And so the combination of these three things, he’s fairly unique in doing that. I guess Google does that. That would be yet another example.\"\n\n\"And so I think he also has the advantage that he loves the intersection between computing and the physical buildouts. He loves that whole area. Nobody knows more about energy than he does.\"\n\n\"One particular new market that we’re going to go explore together is putting data centers out in space. Our two engineering teams are working super closely together to create a new type of server, a new type of architecture that might be super good in space and on Earth.”", "name": "Fireside Alpha", "handle": "firesidealpha", "avatar": "https://pbs.twimg.com/profile_images/2066254089756061697/MGnZGljz_200x200.jpg", "likes": 4235, "rts": 483, "replies": 88, "views": 2457589, "ts": 1792072514, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2110730504534446080/vid/avc1/1280x720/Pf2xgqMeDh1eKdD0.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2110730504534446080/vid/avc1/1920x1080/Ehc-ubEMWCm9ymOh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2110730504534446080/img/WXCc46kIBkkjS28E.jpg", "dur": 67}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.69, "thread": [], "tier": "must"}, {"id": "2112260472246612365", "url": "https://x.com/Argona0x/status/2112260472246612365", "text": "f*cking insane. I hired an AI chief of staff for $0, gave it one rule: \"find me $50,000 a month or you're fired\", went to sleep, and Opus 5.5 had it on my desk by morning\n\na SpaceXAI engineer said one line that hit 5 million views:\n\"i have a Chief of Staff agent. he knows about all my other bots and manages everything\"\n\na human one costs $200,000 a year. mine runs on Opus 5.5 inside Viktor, on his own computer in the cloud, with my laptop shut\n\ni give the goal, he does the steps, i only make the calls\n\nthe rule:\n\"find me $50,000 a month of new business. public data only. contact nobody without my yes\"\n\nthe night:\n→ 9pm broke the goal into 4 jobs and gave each a day and a time, i wrote none of them\n→ 11pm pulled 240 dental clinics in Austin from Google Maps and cut every chain\n→ 1am read every site that was left and kept 25, each with one thing he noticed and where he saw it\n→ 2am wrote an opener for every one of them, sent zero\n→ 3am built the offer on one page, no invented results, price left blank for me instead of guessing\n→ 8am i typed $2,000 a month. 25 clinics × $2,000 = $50,000 a month on the table\n\nhonestly the blank price is what i'd pay for, an AI that guesses your price loses you the deal\n\nand he does it again every Monday: 100 new clinics a month, and he never forgets to start\n\n240 clinics → 25 worth it → 1 offer → $50,000 a month on the table → 0 sent without my yes\n\nsecond 12, he leaves the price blank and hands it to me\n\nsomeone's chief of staff is already pitching the clinics in your city\n\ni left the whole setup below ↓ free, steal it", "name": "Argona", "handle": "Argona0x", "avatar": "https://pbs.twimg.com/profile_images/2074194587824889856/HEijowP__200x200.jpg", "likes": 3365, "rts": 328, "replies": 200, "views": 908743, "ts": 1792437115, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112260382848868352/vid/avc1/720x900/HGwfT14RQI2eVGK_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112260382848868352/vid/avc1/1080x1350/NDSCcomzO9-TNYn2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112260382848868352/img/qICL0miejOGbCrZr.jpg", "dur": 25}], "quote": {"id": "2111152998344757333", "url": "https://x.com/Argona0x/status/2111152998344757333", "text": "https://x.com/i/article/2111112619075538944", "name": "Argona", "handle": "Argona0x", "avatar": "https://pbs.twimg.com/profile_images/2074194587824889856/HEijowP__200x200.jpg", "likes": 253, "rts": 16, "replies": 9, "views": 893011, "ts": 1792173072, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.66, "thread": [], "tier": "must"}, {"id": "2112674550907552137", "url": "https://x.com/humansand/status/2112674550907552137", "text": "No one changes the world alone\nIntroducing Ampersand - the first model built for us. Ampersand is a collaborator trained to help people achieve their individual and collective goals. In multi-month simulations, users collaborating with Ampersand accomplished more than with Fable and other frontier models\nAvailable to everyone through our API", "name": "humans&", "handle": "humansand", "avatar": "https://pbs.twimg.com/profile_images/2013582555933478912/JKuMlTII_200x200.jpg", "likes": 801, "rts": 96, "replies": 70, "views": 115277, "ts": 1792535839, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1280x720/diVwgP2fN9mNUINm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1920x1080/BeqyLOSxKBxRevC6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112664844772278272/img/eMd4u-rAwyUJpqWU.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.65, "thread": [], "tier": "must"}, {"id": "2112320010081501186", "url": "https://x.com/_jxom/status/2112320010081501186", "text": "🚨 Mermaid has been rewritten, again. In Rust!\n\n🧜‍♀️ Introducing Ondine. 🧜‍♀️\n\n- 200B runtime.\n- Renders diagrams in ~50µs.\n- 1,943x smaller, 2.8x faster than Pele.\n- 13,467x smaller, 670x faster than Mermaid.\n- Still 0 dependencies.", "name": "jxom", "handle": "_jxom", "avatar": "https://pbs.twimg.com/profile_images/1686778104151261188/ciEYUUbn_200x200.jpg", "likes": 2908, "rts": 233, "replies": 71, "views": 135381, "ts": 1792451310, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112318412013834240/vid/avc1/1280x720/VHc5jMAkMZRYEHPd.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112318412013834240/vid/avc1/1920x1080/SDRVv6x2yxW4NGqW.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112318412013834240/img/ReTuJjcbHKkpuQdI.jpg", "dur": 51}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.64, "thread": [], "tier": "must"}, {"id": "2112496505399435339", "url": "https://x.com/0xSero/status/2112496505399435339", "text": "Wake up babe \n\nNew deepseek nuke just dropped", "name": "0xSero", "handle": "0xSero", "avatar": "https://pbs.twimg.com/profile_images/2111226379521892352/3ICUbYY6_200x200.jpg", "likes": 1942, "rts": 51, "replies": 20, "views": 101161, "ts": 1792493389, "media": [], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.64, "thread": [], "tier": "must"}, {"id": "2112229620758265938", "url": "https://x.com/OpenAIDevs/status/2112229620758265938", "text": "What have you been cooking with Codex?", "name": "OpenAI Developers", "handle": "OpenAIDevs", "avatar": "https://pbs.twimg.com/profile_images/2022002720971096064/l3Kyt4qt_200x200.jpg", "likes": 2143, "rts": 52, "replies": 1286, "views": 256352, "ts": 1792429759, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.63, "thread": [], "tier": "must"}, {"id": "2112525257072677223", "url": "https://x.com/jenzhuscott/status/2112525257072677223", "text": "This is freakin' crazy - so DeepSeek has 10 month payback on GPU purchase, despite being 20 times cheaper than OpenAI/Anthropic. And they are enabling everyone + every company to have your own AI, your own inference, your own data. \n\nCancel the fucking IPOs 😂 This is so insane 😂", "name": "Jen Zhu", "handle": "jenzhuscott", "avatar": "https://pbs.twimg.com/profile_images/1780838209074966528/sLoqyoHY_200x200.jpg", "likes": 1496, "rts": 123, "replies": 31, "views": 58102, "ts": 1792500244, "media": [], "quote": {"id": "2112488116774990037", "url": "https://x.com/jenzhuscott/status/2112488116774990037", "text": "Wow 🤩 The whale 🐳 isn’t just shipping highly efficient, affordable frontier models - they’re open-sourcing the production inference stack that actually serves them at scale.\n\nDeepInfer (Apache 2.0) powers DeepSeek-V4.1-Flash w the same high-th/put, low-latency runtime used in production. It includes optimized kernels, Attention DP / balanced CP, MoE EP + EPLB, DSpark speculative decoding w confidence-scheduled verification, SWA bounded replay (to cut prefill work), 0-overhead asynchronous scheduling, batch-invariant inference, deterministic sampling, + structured outputs. \n\nOffline inference examples run from local Hugging Face checkpoints w no network required once the weights are cached. They also open-sourced deepseek-recipe, the production tokenizer/encoding path so community deployments match official API behavior.\n\nOpen models + open kernels + open production inference. That’s a meaningfully different trajectory the whale 🐳 is offering to the world. I freakin love these guys 💙🥹💙", "name": "Jen Zhu", "handle": "jenzhuscott", "avatar": "https://pbs.twimg.com/profile_images/1780838209074966528/sLoqyoHY_200x200.jpg", "likes": 346, "rts": 50, "replies": 8, "views": 66432, "ts": 1792491389, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.63, "thread": [], "tier": "must"}, {"id": "2112496667236905046", "url": "https://x.com/theo/status/2112496667236905046", "text": "Got a repo on one PC and want to work on it from another? Takes 2 clicks now :)\n\nEven handles .gitignore'd files like .env if you have them in the repo", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1642, "rts": 18, "replies": 169, "views": 69858, "ts": 1792493428, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112496531886747648/vid/avc1/1106x720/c0M4iTTaXPWakZI5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112496531886747648/vid/avc1/1660x1080/iiv26470VSii2h1d.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112496531886747648/img/yIk-m9lyJ8X7RtgU.jpg", "dur": 27}], "quote": {"id": "2112432426861654160", "url": "https://x.com/theo/status/2112432426861654160", "text": "There's a feature I've wanted in T3 Code for months that was really complex UX wise and I couldn't figure out how to get it right.\n\nJust had it click. I'm hyped. Will seem really small when it drops, but it will make things much easier for us multi-machine agent wranglers :)", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 1144, "rts": 10, "replies": 97, "views": 101931, "ts": 1792478112, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.62, "thread": [], "tier": "must"}, {"id": "2112422267829334176", "url": "https://x.com/dhh/status/2112422267829334176", "text": "Grok Bot is running Try Omarchy inside its own computer. So you can develop plugins and applications with it. Pretty sweet!", "name": "DHH", "handle": "dhh", "avatar": "https://pbs.twimg.com/profile_images/2093715898204884992/goERjC9G_200x200.jpg", "likes": 1993, "rts": 75, "replies": 92, "views": 88634, "ts": 1792475690, "media": [], "quote": {"id": "2112396640225054989", "url": "https://x.com/tcballard/status/2112396640225054989", "text": "I now have a @Bot with its own Omarchy machine. That’s fricken cool 😅\n\nHere it is switching themes, tiling windows and opening my markets widget. Fairly ordinary desktop stuff, until you remember who’s driving.\n\nIt means I can start delegating visual QA for my plugins. Have it open panels, try different themes, check layouts and show me what actually happens on screen.\n\nStill some tweaks needed for cloud setups like this (help a fella out @poteto) but having another pair of eyes and a separate machine to test on is a pretty exciting step.\n\nI gave my bot a Linux desktop. Naturally, I’m putting it to work.", "name": "Tom Ballard", "handle": "tcballard", "avatar": "https://pbs.twimg.com/profile_images/2109327988940558336/ZEHDs0lC_200x200.jpg", "likes": 423, "rts": 17, "replies": 29, "views": 114819, "ts": 1792469580, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112396608591499264/vid/avc1/1152x720/VHxSYgtP1YN5ZSZU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112396608591499264/vid/avc1/1280x800/ziLMmGI-UczYTsxX.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112396608591499264/img/MiRXz-nG85AEC0ID.jpg", "dur": 42}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.59, "thread": [], "tier": "must"}, {"id": "2112574574718050575", "url": "https://x.com/LeadpoetAI/status/2112574574718050575", "text": "We just killed cold outreach.\n\nIntroducing Leadpoet: the AI sales agent that finds buyers who need you now, writes personalized outreach, and follows up on LinkedIn and email.\n\nUsed by Dropbox, OnePatch (YC26), Muttdata.\n\nComment “Poet” for 100 free lead credits to find qualified buyers.", "name": "Leadpoet", "handle": "LeadpoetAI", "avatar": "https://pbs.twimg.com/profile_images/1985417271552921600/7WFD_3H5_200x200.jpg", "likes": 452, "rts": 78, "replies": 397, "views": 90324, "ts": 1792512003, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112561333925294082/vid/avc1/1280x720/97xhMUyn5RT0OFL5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112561333925294082/vid/avc1/3840x2160/rkr6MBEAGx5hzqMx.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112561333925294082/img/1BnpmZbKluTgyPpN.jpg", "dur": 83}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.59, "thread": [], "tier": "must"}, {"id": "2112546905154580675", "url": "https://x.com/0x_fokki/status/2112546905154580675", "text": "I seriously don't understand why schools don't use this yet.\n\nI've been working on the same idea with Claude! A skill that builds everyday machines you can take apart and play with.\n\nJust built a mechanical watch and added it to the site last night. You can wind it, flip it open and watch the little wheel inside tick 8 times a second, 691,200 times a day.\n\nTry it yourself, link in the first reply 👇", "name": "Fokki", "handle": "0x_fokki", "avatar": "https://pbs.twimg.com/profile_images/2058811986180194304/b_xYlbny_200x200.jpg", "likes": 1133, "rts": 115, "replies": 48, "views": 45269, "ts": 1792505406, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112546857800921088/vid/avc1/936x720/QsnCuAp5FeCdJuWW.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112546857800921088/vid/avc1/1500x1152/lCtqmzp8KywqZHky.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112546857800921088/img/SLhsGNBqYqL9mm4K.jpg", "dur": 35}], "quote": {"id": "2111831136171151589", "url": "https://x.com/elvar_official/status/2111831136171151589", "text": "https://x.com/i/article/2111753944061902848", "name": "Elvar", "handle": "elvar_official", "avatar": "https://pbs.twimg.com/profile_images/2104503094914498560/fV9eZood_200x200.jpg", "likes": 317, "rts": 49, "replies": 15, "views": 116849, "ts": 1792334753, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.58, "thread": [], "tier": "must"}, {"id": "2112671665088024744", "url": "https://x.com/theo/status/2112671665088024744", "text": "Opus 5.5 is proof that the world does actually need smarter models.", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 908, "rts": 22, "replies": 50, "views": 75868, "ts": 1792535151, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112668735467393024/vid/avc1/1280x720/XVhyNR1EWNCxghnK.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112668735467393024/vid/avc1/3840x2160/i_FFwvOyrifv4Ioz.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112668735467393024/img/79K9L309tKOhXjcb.jpg", "dur": 1872}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.58, "thread": [], "tier": "must"}]);